/** A certificate design as the editor shows it: empty text means "use the default". */

export const CERTIFICATE_TEMPLATES = ['classic', 'modern', 'minimal', 'academic'];
export const CERTIFICATE_IMAGES = ['logo', 'background', 'signature'];
const api = path => app.forum.attribute('apiUrl') + '/syllabus' + path;
function call(method, path, body, params) {
  return app.request({
    method,
    url: api(path),
    body: body ? {
      data: body
    } : undefined,
    params
  });
}

/** A multipart upload: `serialize` hands the FormData to the browser untouched. */
export function upload(path, form) {
  return app.request({
    method: 'POST',
    url: api(path),
    body: form,
    serialize: raw => raw
  });
}
